        "تم تغيير التخصصات": "تم تغيير التخصصات",
        "تم تغيير الفئات العمرية": "تم تغيير الفئات العمرية",
        "تم تغيير الملاحظات (الترويج)": "تم تغيير الملاحظات (الترويج)",
        "تم تغيير رابط المرفق (الترويج)": "تم تغيير رابط المرفق (الترويج)",
        "نظام": "نظام",
        ...notifyTranslationsAr,
      },
    };
    return raw.map((locale, map) => MapEntry(locale, _normalizeMapDigits(map)));
  }
}
